import sys

def main():
    s = sys.stdin.readline().rstrip('\n')
    print(s[::-1])
    print(s.upper())
    cnt = {}
    for ch in s:
        cnt[ch] = cnt.get(ch, 0) + 1
    for ch in s:
        if cnt[ch] == 1:
            print(ch)
            return
    print("No non-repeated character found.")

if __name__ == "__main__":
    main()
